procedure BrewReorder {
  about "Reorder kegs with few left"
  policy BrewPolicy
  sheet Kegs "Kegs" { beer: Text, on_hand: Number, reorder_count: Number, partner: Text, keg_price: Money }
  trigger every day at 09:00

  let all = fetch Kegs
  let low = filter all where on_hand < 2
  for each i in low up to 3 {
    let cost = i.reorder_count * i.keg_price
    if cost > $250.00 {
      notify owner "Reorder of {i.beer} would cost {cost}, over the $250 limit."
      skip
    }
    order "{i.reorder_count} x {i.beer}" from i.partner cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.beer}"
  }
}

procedure BrewDailySummary {
  about "Tell the owner how many kegs are empty and their average price"
  policy BrewPolicy
  sheet Kegs "Kegs" { beer: Text, on_hand: Number, reorder_count: Number, partner: Text, keg_price: Money }
  trigger every sunday at 23:00

  let all = fetch Kegs
  let these = filter all where on_hand == 0.0
  let n = summarize count of these
  let total = summarize sum keg_price of these
