procedure CampgroundRefunds {
  about "Handle refunds within limits"
  policy CampgroundPolicy
  sheet Cancellations "Cancellations" { booking: Text, camper: Text, deposit: Money, arrival: Date }
  trigger when new row r in Cancellations

  if r.arrival < today() + 5 days {
    notify owner "Refund of {r.deposit} for {r.camper} would be within 5 days."
    stop "outside refund window"
  }
  if r.deposit > $150.00 {
    notify owner "Refund of {r.deposit} for {r.camper} would be over $150. Please review."
    stop "over refund limit"
  }
  if r.deposit <= $50.00 {
    refund r.deposit for r.booking reason "refund request"
  } else {
    refund r.deposit for r.booking reason "refund request", ask owner first timeout 12 hours else stop "refund not approved"
  }
}

