procedure TailorFollowUpAfterWait {
  about "Contact a customer after they're ready, then follow up once"
  policy TailorPolicy
  sheet ReadyLog "ReadyLog" { ticket: Text, customer: Text, phone: Phone }
  sheet Alterations "Alterations" { ticket: Text, customer: Text, phone: Phone, due: Date, price: Money, status: Text, measurements: Text private }
  trigger when new row r in ReadyLog

  let first = draft sms to r.phone: "Hi {r.customer}, your alteration is ready! Reply with any questions."
  let ok1 = request approval of first from owner timeout 12 hours else skip
  send ok1
  wait 7 days
  let all = fetch Alterations
  for each i in all up to 1 {
    if i.ticket == r.ticket {
      let second = draft sms to i.phone: "Hi {i.customer default 'there'}, just checking in. Is there anything we can help with?"
      let ok2 = request approval of second from owner timeout 12 hours else skip
      send ok2
      break
    }
  }
}

